-- ============ JADWAL PELAJARAN ============
-- 5 hari (senin-jumat), 8 jam/hari, jam 4 & 5 = istirahat
-- 10 guru assigned to 5 mapel (2 guru per mapel):
--   MTK: Guru 1 (Siti), Guru 2 (Budi)
--   BIN: Guru 3 (Dewi), Guru 4 (Andi)
--   BIG: Guru 5 (Rina), Guru 6 (Agus)
--   IPA: Guru 7 (Fitri), Guru 8 (Hendra)
--   IPS: Guru 9 (Nurul), Guru 10 (Wahyu)
-- Schedule ensures no guru teaches 2 classes at same time

-- SENIN
-- Jam 1: 7A=MTK(G1), 7B=BIN(G3), 8A=BIG(G5), 8B=IPA(G7), 9A=IPS(G9), 9B=MTK(G2)
-- Jam 2: 7A=MTK(G1), 7B=BIN(G3), 8A=BIG(G5), 8B=IPA(G7), 9A=IPS(G9), 9B=MTK(G2)
-- Jam 3: 7A=BIN(G4), 7B=MTK(G2), 8A=IPA(G8), 8B=BIG(G6), 9A=MTK(G1), 9B=IPS(G10)
-- Jam 4: ISTIRAHAT
-- Jam 5: ISTIRAHAT
-- Jam 6: 7A=BIG(G5), 7B=IPA(G7), 8A=MTK(G1), 8B=BIN(G3), 9A=BIG(G6), 9B=IPA(G8)
-- Jam 7: 7A=BIG(G5), 7B=IPA(G7), 8A=MTK(G1), 8B=BIN(G3), 9A=BIG(G6), 9B=IPA(G8)
-- Jam 8: 7A=IPS(G9), 7B=IPS(G10), 8A=BIN(G4), 8B=MTK(G2), 9A=IPA(G7), 9B=BIN(G3)

