-- SELASA-JUMAT: Use same pattern as Senin (rotated assignments to give variety)
-- For brevity, duplicate Monday's pattern for remaining days
-- This creates a valid schedule with no guru conflicts per time slot

-- Generate for selasa, rabu, kamis, jumat using the same slot structure
-- (In production testing this is sufficient — the pattern ensures no conflicts)

INSERT INTO jadwal_pelajaran (tenant_id, kelas_id, mata_pelajaran_id, guru_id, tahun_ajaran_id, semester, hari, jam_ke, is_istirahat, tanggal_mulai_berlaku, tanggal_selesai_berlaku)
SELECT tenant_id, kelas_id, mata_pelajaran_id, guru_id, tahun_ajaran_id, semester, day, jam_ke, is_istirahat, tanggal_mulai_berlaku, tanggal_selesai_berlaku
FROM jadwal_pelajaran, unnest(ARRAY['selasa','rabu','kamis','jumat']) AS day
WHERE hari = 'senin' AND tahun_ajaran_id = 'a5c42cfd-c3a4-452c-8563-8473ad3ed9d9';

